def _C_fast(h):
    """C computed via FFT; faster for larger N, exact enough for ranking."""
    s = h.sum()
    if s <= 0:
        return np.inf
    n = len(h)
    nfft = 1
    while nfft < 2 * n - 1:
        nfft <<= 1
    F = np.fft.rfft(h, nfft)
    conv = np.fft.irfft(F * F, nfft)[: 2 * n - 1]
    return 2.0 * n * np.max(conv) / (s * s)


