    bestC = _C(best)
    print(f"start C={bestC:.6f} N={len(best)}")

    rng = np.random.default_rng(12345)

    def norm(h):
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            return None
        return h / s

    def resample(h, N):
        m = h.size
        xi = (np.arange(N) + 0.5) / N * m - 0.5
        xi = np.clip(xi, 0, m - 1)
        i0 = np.floor(xi).astype(int)
        i1 = np.minimum(i0 + 1, m - 1)
        f = xi - i0
        return h[i0] * (1 - f) + h[i1] * f

    # ---- Key move: coordinate descent on log-heights, which is scale free
    #      and naturally positive. Also we do a "shift" step that reflects
    #      the symmetry: the optimum should be symmetric, so symmetrize. ----
    def symmetrize(h):
        return 0.5 * (h + h[::-1])

    def refine(h, cur, dl, max_rounds=200):
        h = h.copy()
        n = h.size
        logh = np.log(np.maximum(h, 1e-12))
