        if cs < bestC:
            bestC = cs
            best = bs

    # ---- Main loop: for a range of N, refine and keep the best ----
    # Focus on small N (the optimum seems to live around N ~ 30-100), but
    # also test larger N briefly.
    Ns_to_try = [best.size]
    for N in [30, 40, 45, 50, 55, 60, 70, 80, 100, 120, 150, 200, 300]:
        if N not in Ns_to_try:
            Ns_to_try.append(N)

    it = 0
    while time_left() > 0.3 and it < 10000:
        it += 1
        # pick next N (cycle through, with random choice)
        if it <= len(Ns_to_try):
            N = Ns_to_try[it - 1]
        else:
            # perturb: resample best at a nearby N or perturb heights
            if rng.random() < 0.5:
                N = best.size
                h = best * (1.0 + 0.05 * rng.standard_normal(best.size))
                h = norm(h)
                if h is None:
                    continue
            else:
                N = max(20, min(30000, best.size + int(rng.integers(-10, 11))))
                if N == best.size:
                    N = best.size + 1
                h = resample(best, N)
                h = norm(h)
                if h is None:
                    continue
        h = resample(best, N)
        h = norm(h)
        if h is None:
            continue
        h = symmetrize(h)
        h = norm(h)
        c = _C(h)
        sub_dl = min(deadline, time.process_time() + max(0.3, time_left() / 3))
        h, c = refine(h, c, sub_dl)
        h = symmetrize(h)
        h = norm(h)
        c = _C(h)
        if c < bestC - 1e-12:
            best, bestC = h.copy(), c

    # ---- Final polish on the best ----
    if time_left() > 0.2:
        h, c = refine(best, bestC, deadline)
        h = symmetrize(h)
        h = norm(h)
        c = _C(h)
        if c < bestC:
            best, bestC = h, c

    print(f"final C={bestC:.6f} N={len(best)} iters={it}")
    return np.asarray(np.maximum(best, 0.0), dtype=float)
